// Bundles React, ReactDOM (profiling build), and D3 into modular self-contained bundles
// for the sandboxed preview iframe (srcdoc, sandbox="allow-scripts").
// Run: node scripts/build-preview-bundle.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const here = path.dirname(fileURLToPath(import.meta.url));
const tmp = path.join(here, '.tmp-preview-entry.js');
fs.writeFileSync(
  tmp,
  `import * as React from 'react';
import * as ReactDOM from 'react-dom/profiling';
window.React = React;
window.ReactDOM = ReactDOM;
`
);

try {
  const res = await build({
    configFile: false,
    define: { 'process.env.NODE_ENV': JSON.stringify('production') },
    build: {
      write: false,
      minify: true,
      lib: {
        entry: tmp,
        formats: ['iife'],
        name: 'ReactBundle',
      },
    },
  });
  const reactCode = res[0].output[0].code;

  const d3Path = path.join(here, '../node_modules/d3/dist/d3.min.js');
  const d3Code = fs.readFileSync(d3Path, 'utf8');

  const outPath = path.join(here, '..', 'src/lib/reactPreviewBundle.ts');
  fs.writeFileSync(
    outPath,
    `// Auto-generated by scripts/build-preview-bundle.mjs - do not edit manually\nexport const REACT_PREVIEW_BUNDLE = ${JSON.stringify(reactCode)};\nexport const D3_PREVIEW_BUNDLE = ${JSON.stringify(d3Code)};\n`
  );
  console.log(`Generated reactPreviewBundle.ts (${(fs.statSync(outPath).size / 1024).toFixed(1)} KB)`);
} finally {
  if (fs.existsSync(tmp)) fs.unlinkSync(tmp);
}
